// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 initialAmount, uint256 addAmount, address sender) public {
        vm.assume(initialAmount > 0);
        vm.assume(addAmount > 0);
        vm.assume(initialAmount <= type(uint256).max - addAmount);
        vm.assume(sender != address(0));
        vm.assume(sender != address(c));

        vm.deal(sender, initialAmount + addAmount);
        vm.prank(sender);
        c.addToBalance{value: initialAmount}();

        uint256 balanceBefore = c.getBalance(sender);

        vm.prank(sender);
        c.addToBalance{value: addAmount}();

        uint256 balanceAfter = c.getBalance(sender);
        assertTrue(balanceAfter >= balanceBefore + addAmount);
    }
}
